-- function public.has_course_access(_user_id bigint, _course_id bigint)
-- Generated by db/tools/export-schema.mjs from the live database. Do not edit by hand:
-- change the database through a migration in db/migrations, then re-run the exporter.

CREATE OR REPLACE FUNCTION public.has_course_access(_user_id bigint, _course_id bigint)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
    SELECT EXISTS (
        SELECT 1
        FROM commerce.entitlement e
        JOIN catalog.course c ON c.id = e.course_id
        WHERE e.user_id = _user_id
          AND e.course_id = _course_id
          AND e.status = 'active'
          AND (e.expires_at IS NULL OR e.expires_at > now())
          AND c.is_deleted = false
          AND c.publish_status <> 'archived'
    );
$function$;
